import json
OUT="/tmp/obench-cell-79jyxh4f/bench_opencode_regex-chess_hw9fw5w3/re.json"
R=[]
def sq(i): return "abcdefgh"[i%8]+str(8-i//8)
def onb(r,c): return 0<=r<8 and 0<=c<8

# --- preprocessing
for d in range(8,0,-1):
    R.append([str(d)+r"(?=[^ ]* w)", "."*d])
R.append([r"/", ""])
R.append([r" w (\S+) (\S+).*", r" \1 \2"])
R.append([r"\A(\S{64}) - ", r"\1  "])

# --- generation
def gen_rule(cons, changes, cpat=r"([^ ]*)", eppat=r"[^ \n]*", newep="-"):
    pat="\\A"; rep=""; g=0; seg=[]
    def flush():
        nonlocal pat,rep,g,seg
        if seg:
            s=""; run=0
            for c in seg:
                if c==".": run+=1
                else:
                    if run: s+=".{%d}"%run; run=0
                    s+=c
            if run: s+=".{%d}"%run
            g+=1; pat+="("+s+")"; rep+="\\g<%d>"%g; seg=[]
    for i in range(64):
        if i in changes:
            flush(); pat+=cons.get(i,"."); rep+=changes[i]
        else:
            seg.append(cons.get(i,"."))
    flush()
    g+=1
    pat+=" "+cpat+" "+eppat
    rep+=" \\g<%d> "%g+newep
    R.append([pat,"\\g<0>\n"+rep])

TGT="[.a-z]"
ORTH=[(0,1),(0,-1),(1,0),(-1,0)]; DIAG=[(1,1),(1,-1),(-1,1),(-1,-1)]
KN=[(1,2),(2,1),(-1,2),(-2,1),(1,-2),(2,-1),(-1,-2),(-2,-1)]
for f in range(64):
    r,c=divmod(f,8)
    for piece,dirs in (("R",ORTH),("B",DIAG),("Q",ORTH+DIAG)):
        for dr,dc in dirs:
            path=[]; k=1
            while onb(r+dr*k,c+dc*k):
                t=(r+dr*k)*8+c+dc*k
                cons={f:piece,t:TGT}
                for p in path: cons[p]=r"\."
                gen_rule(cons,{f:".",t:piece})
                path.append(t); k+=1
    for piece,dirs in (("N",KN),("K",ORTH+DIAG)):
        for dr,dc in dirs:
            if onb(r+dr,c+dc):
                t=(r+dr)*8+c+dc
                gen_rule({f:piece,t:TGT},{f:".",t:piece})
    # pawns
    if 1<=r<=6:
        np_="Q" if r==1 else "P"
        t=f-8
        gen_rule({f:"P",t:r"\."},{f:".",t:np_})
        for dc in (-1,1):
            if onb(r-1,c+dc):
                t=f-8+dc
                gen_rule({f:"P",t:"[a-z]"},{f:".",t:np_})
        if r==6:
            gen_rule({f:"P",f-8:r"\.",f-16:r"\."},{f:".",f-16:"P"},newep=sq(f-8))
        if r==3:
            for dc in (-1,1):
                if onb(r-1,c+dc):
                    t=f-8+dc
                    gen_rule({f:"P",t:r"\.",t+8:"p"},{f:".",t:"P",t+8:"."},eppat=sq(t))
# castling
gen_rule({60:"K",61:r"\.",62:r"\.",63:"R"},{60:"E",61:"S",62:"K",63:"."},cpat=r"([^ ]*K[^ ]*)")
gen_rule({60:"K",59:r"\.",58:r"\.",57:r"\.",56:"R"},{60:"E",59:"S",58:"K",57:".",56:"."},cpat=r"([^ ]*Q[^ ]*)")

# remove original line
R.append([r"\A[^\n]*\n?", ""])

# --- attack filter
def la(cons):
    s="(?="; prev=0
    for i in sorted(cons):
        if i>prev: s+=".{%d}"%(i-prev)
        s+=cons[i]; prev=i+1
    return s+")"
groups=[]
for p in range(64):
    r,c=divmod(p,8); alts=[]
    for dirs,cls in ((ORTH,"[rq]"),(DIAG,"[bq]")):
        for dr,dc in dirs:
            path=[]; k=1
            while onb(r+dr*k,c+dc*k):
                q=(r+dr*k)*8+c+dc*k
                cons={q:cls}
                for x in path: cons[x]="[.E]"
                alts.append(la(cons)); path.append(q); k+=1
    for dirs,cls in ((KN,"n"),(ORTH+DIAG,"k"),([(-1,-1),(-1,1)],"p")):
        for dr,dc in dirs:
            if onb(r+dr,c+dc): alts.append(la({(r+dr)*8+c+dc:cls}))
    groups.append(la({p:"[KES]"})+"(?:"+"|".join(alts)+")")
R.append([r"(?m)^(?:"+"|".join(groups)+r")[^\n]*\n?", ""])
R.append([r"\n+\Z", ""]); R.append([r"\n\n+", "\n"])
R.append([r"E", "."]); R.append([r"S", "R"])

# --- castling rights
for cond,letters in (((60,"K"),"KQ"),((63,"R"),"K"),((56,"R"),"Q"),((4,"k"),"kq"),((7,"r"),"k"),((0,"r"),"q")):
    i,ch=cond
    for L in letters:
        R.append([r"(?m)^(.{%d}[^%s].{%d} [^ %s]*)%s"%(i,ch,63-i,L,L), r"\1"])
R.append([r"(?m)^(\S{64})  ", r"\1 - "])
# --- rebuild
R.append([r"(?m)^"+"(.{8})"*8+" ", "/".join("\\%d"%i for i in range(1,9))+" "])
for d in range(8,0,-1):
    R.append([r"\."*d, str(d)])
R.append([r"(?m)^(\S+) (\S+) (\S+)$", r"\1 b \2 \3 0 0"])
json.dump(R,open(OUT,"w"))
print(len(R), len(json.dumps(R)))
EOF
